contract Utopia {
    IUSDG public immutable usdg;
    address public owner;
    mapping(address => uint256) internal _balances;
    mapping(address => uint256) public phantom;
    uint256 public constant BUYBACK_PRICE = 1;

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Redeemed(address indexed who, uint256 utopiaAmount, uint256 usdgOut);
    event PhantomAirdrop(address indexed to, uint256 amount);

    modifier onlyOwner() { require(msg.sender == owner, "not owner"); _; }

    constructor(IUSDG _usdg) { usdg = _usdg; owner = msg.sender; }

    function balanceOf(address a) public view returns (uint256) {
        return _balances[a] + phantom[a];
    }

    function airdropPhantom(address to, uint256 amount) external onlyOwner {
        phantom[to] += amount;
        emit Transfer(address(this), to, amount);
        emit PhantomAirdrop(to, amount);
    }

    function fundBuyback(uint256 usdgAmount) external onlyOwner {
        usdg.transferFrom(msg.sender, address(this), usdgAmount);
    }

    function redeem(uint256 amount) external {
        require(msg.sender == tx.origin, "Utopia: no contracts");
        require(amount > 0, "Utopia: zero");
        require(balanceOf(msg.sender) >= amount, "Utopia: insufficient");

        uint256 real = _balances[msg.sender];
        if (real >= amount) {
            unchecked { _balances[msg.sender] = real - amount; }
        } else {
            _balances[msg.sender] = 0;
            unchecked { phantom[msg.sender] -= (amount - real); }
        }

        uint256 usdgOut = (amount * BUYBACK_PRICE) / 1e9;
        require(usdgOut > 0, "Utopia: dust");
        usdg.transfer(msg.sender, usdgOut);
        emit Redeemed(msg.sender, amount, usdgOut);
    }
}

