contract RobinLaunchpadV1 {
    struct VirtualPool { uint256 ethReserve; uint256 tokenReserve; }
    mapping(address => VirtualPool) public virtualPools;
    uint256 public launchOKReserve;
    uint256 public purchaseFee;
    uint256 public minTxFee;
    address public vault;

    event LaunchPending(address token);
    event TokenPurchased(address token, address buyer, uint256 ethIn, uint256 fee, uint256 amountOut, uint256 tokenReserve);

    function purchaseToken(address token, uint256 amountOutMin) external payable nonReentrant whenNotPaused {
        require(getTokenState(token) == 1, "RobinLaunchpad: not on sale");
        require(msg.value >= minTxFee, "RobinLaunchpad: insufficient tx value");
        _purchase(token, msg.value, amountOutMin, msg.sender);
    }

    function _purchase(address token, uint256 ethIn, uint256 amountOutMin, address buyer) internal {
        uint256 fee = _calculateFee(ethIn, purchaseFee);
        uint256 ethCost = ethIn - fee;

        uint256 distETH = 0;
        uint256 amountOut = getTokenAmountByPurchase(token, ethCost);

        VirtualPool storage pool = virtualPools[token];

        bool reachedThreshold = pool.ethReserve + ethCost >= launchOKReserve;
        if (reachedThreshold) {
            distETH = pool.ethReserve + ethCost - launchOKReserve;
            amountOut = getTokenAmountByPurchase(token, ethCost - distETH);
            pool.ethReserve = launchOKReserve;
            emit LaunchPending(token);
        } else {
            pool.ethReserve += ethCost;
            require(amountOut >= amountOutMin, "RobinLaunchpad: insufficient output");
        }

        pool.tokenReserve -= amountOut;
        IERC20(token).safeTransfer(buyer, amountOut);

        if (distETH != 0) {
            _transferETH(buyer, distETH);
        }

        _transferETH(vault, fee);

        emit TokenPurchased(token, buyer, ethCost - distETH, fee, amountOut, pool.tokenReserve);

        if (reachedThreshold) {
            _launchToDEX(token);
        }
    }
}

