contract RwaVault {
    IERC20Basket public token;
    address public swapper;
    address public owner;
    bool public redemptionOpen;
    address[] private _assets;
    mapping(address => bool) public isAsset;
    uint256 public constant MAX_CONVERT_BPS = 2000;
    uint256 public constant BPS = 10000;
    uint256 public constant MAX_ASSETS = 32;

    modifier onlyOwner() { require(msg.sender == owner, "not owner"); _; }

    function addAsset(address asset) external onlyOwner {
        if (asset == address(0)) revert ZeroAddress();
        if (asset == address(token)) revert NotAnAsset();
        if (isAsset[asset]) revert AlreadyAsset();
        if (_assets.length >= MAX_ASSETS) revert TooManyAssets();
        isAsset[asset] = true;
        _assets.push(asset);
        emit AssetAdded(asset);
    }

    function openRedemption() external onlyOwner {
        redemptionOpen = true;
        emit RedemptionOpened();
    }

    receive() external payable { emit EthReceived(msg.sender, msg.value); }

    function convert(address assetOut, uint256 ethIn, uint256 minOut, bytes calldata route)
        external
        nonReentrant
        onlyOwner
        returns (uint256 gained)
    {
        if (swapper == address(0)) revert NoSwapper();
        if (!isAsset[assetOut]) revert NotAnAsset();
        if (ethIn == 0 || minOut == 0) revert ZeroAmount();

        uint256 cap = (address(this).balance * MAX_CONVERT_BPS) / BPS;
        if (ethIn > cap) revert ConvertTooLarge(ethIn, cap);

        uint256 before = IERC20Basket(assetOut).balanceOf(address(this));
        IBasketSwapper(swapper).swapEthForAsset{value: ethIn}(route, minOut);
        gained = IERC20Basket(assetOut).balanceOf(address(this)) - before;

        if (gained < minOut) revert ConvertSlippage(gained, minOut);
        emit Converted(assetOut, ethIn, gained);
    }
}

