contract RwaVault {
    IERC20Basket public token;
    address public constant BURN = 0x000000000000000000000000000000000000dEaD;
    bool public redemptionOpen;
    address[] private _assets;
    mapping(address => uint256) public totalDeferred;
    mapping(address => mapping(address => uint256)) public owedAsset;
    uint256 private constant SEND_GAS = 100000;

    function claimBasis() public view returns (uint256) {
        return token.totalSupply() - token.balanceOf(address(this)) - token.balanceOf(BURN);
    }

    function available(address asset) public view returns (uint256) {
        return IERC20Basket(asset).balanceOf(address(this)) - totalDeferred[asset];
    }

    function redeem(uint256 tokenAmount) external nonReentrant returns (uint256 basis) {
        if (!redemptionOpen) revert RedemptionClosed();
        if (tokenAmount == 0) revert ZeroAmount();

        basis = claimBasis();
        if (tokenAmount > basis) revert ExceedsClaimBasis();

        uint256 ethPayout = (address(this).balance * tokenAmount) / basis;

        token.transferFrom(msg.sender, address(this), tokenAmount);

        uint256 len = _assets.length;
        for (uint256 i = 0; i < len; i++) {
            address asset = _assets[i];
            uint256 payout = (available(asset) * tokenAmount) / basis;
            if (payout == 0) continue;
            if (_trySend(asset, msg.sender, payout)) {
                emit PaidOut(msg.sender, asset, payout);
            } else {
                owedAsset[msg.sender][asset] += payout;
                totalDeferred[asset] += payout;
                emit PayoutDeferred(msg.sender, asset, payout);
            }
        }
        if (ethPayout > 0) {
            (bool ok,) = msg.sender.call{value: ethPayout}("");
            if (!ok) revert TransferFailed();
            emit EthPaidOut(msg.sender, ethPayout);
        }
        emit Redeemed(msg.sender, tokenAmount, basis);
    }

    function claimDeferred(address asset) external nonReentrant returns (uint256 amount) {
        amount = owedAsset[msg.sender][asset];
        if (amount == 0) revert NothingDeferred();
        owedAsset[msg.sender][asset] = 0;
        totalDeferred[asset] -= amount;
        if (!_trySend(asset, msg.sender, amount)) revert TransferFailed();
        emit DeferredClaimed(msg.sender, asset, amount);
    }

    function _trySend(address asset, address to, uint256 amount) private returns (bool ok) {
        bytes memory data = abi.encodeCall(IERC20Basket.transfer, (to, amount));
        uint256 rds;
        uint256 word;
        assembly {
            ok := call(SEND_GAS, asset, 0, add(data, 0x20), mload(data), 0, 0)
            rds := returndatasize()
            if iszero(lt(rds, 0x20)) {
                returndatacopy(0x00, 0x00, 0x20)
                word := mload(0x00)
            }
        }
        if (!ok) return false;
        if (rds == 0) return true;
        return rds >= 32 && word != 0;
    }
}

pragma solidity ^0.8.20;

abstract contract ERC20 is Context, IERC20, IERC20Metadata, IERC20Errors {
    mapping(address account => uint256) private _balances;
    mapping(address account => mapping(address spender => uint256)) private _allowances;
    uint256 private _totalSupply;

    function transfer(address to, uint256 value) public virtual returns (bool) {
        address owner = _msgSender();
        _transfer(owner, to, value);
        return true;
    }

    function transferFrom(address from, address to, uint256 value) public virtual returns (bool) {
        address spender = _msgSender();
        _spendAllowance(from, spender, value);
        _transfer(from, to, value);
        return true;
    }

    function _transfer(address from, address to, uint256 value) internal {
        if (from == address(0)) { revert ERC20InvalidSender(address(0)); }
        if (to == address(0)) { revert ERC20InvalidReceiver(address(0)); }
        _update(from, to, value);
    }

    function _update(address from, address to, uint256 value) internal virtual {
        if (from == address(0)) {
            _totalSupply += value;
        } else {
            uint256 fromBalance = _balances[from];
            if (fromBalance < value) {
                revert ERC20InsufficientBalance(from, fromBalance, value);
            }
            unchecked { _balances[from] = fromBalance - value; }
        }

        if (to == address(0)) {
            unchecked { _totalSupply -= value; }
        } else {
            unchecked { _balances[to] += value; }
        }

        emit Transfer(from, to, value);
    }

    function _spendAllowance(address owner, address spender, uint256 value) internal virtual {
        uint256 currentAllowance = allowance(owner, spender);
        if (currentAllowance < type(uint256).max) {
            if (currentAllowance < value) {
                revert ERC20InsufficientAllowance(spender, currentAllowance, value);
            }
            unchecked { _approve(owner, spender, currentAllowance - value, false); }
        }
    }
}

pragma solidity ^0.8.20;

library ECDSA {
    enum RecoverError { NoError, InvalidSignature, InvalidSignatureLength, InvalidSignatureS }

    function tryRecover(bytes32 hash, bytes memory signature) internal pure returns (address, RecoverError, bytes32) {
        if (signature.length == 65) {
            bytes32 r;
            bytes32 s;
            uint8 v;
            assembly {
                r := mload(add(signature, 0x20))
                s := mload(add(signature, 0x40))
                v := byte(0, mload(add(signature, 0x60)))
            }
            return tryRecover(hash, v, r, s);
        } else {
            return (address(0), RecoverError.InvalidSignatureLength, bytes32(signature.length));
        }
    }

    function tryRecover(bytes32 hash, uint8 v, bytes32 r, bytes32 s)
        internal pure returns (address, RecoverError, bytes32)
    {
        if (uint256(s) > 0x7FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF5D576E7357A4501DDFE92F46681B20A0) {
            return (address(0), RecoverError.InvalidSignatureS, s);
        }

        address signer = ecrecover(hash, v, r, s);
        if (signer == address(0)) {
            return (address(0), RecoverError.InvalidSignature, bytes32(0));
        }

        return (signer, RecoverError.NoError, bytes32(0));
    }

    function recover(bytes32 hash, uint8 v, bytes32 r, bytes32 s) internal pure returns (address) {
        (address recovered, RecoverError error, bytes32 errorArg) = tryRecover(hash, v, r, s);
        _throwError(error, errorArg);
        return recovered;
    }
}
